CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_user_id BIGINT UNSIGNED NULL, name VARCHAR(160) NOT NULL, username VARCHAR(80) NULL UNIQUE, email VARCHAR(190) NULL UNIQUE, password VARCHAR(255) NOT NULL, account_type ENUM('admin','owner','child') NOT NULL DEFAULT 'owner', can_view_audit TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_users_parent FOREIGN KEY(parent_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, project_key VARCHAR(100) NOT NULL, description TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_project_owner_key(owner_id,project_key), CONSTRAINT fk_projects_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS environments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, env_key ENUM('staging','production') NOT NULL, name VARCHAR(80) NOT NULL, current_version_id BIGINT UNSIGNED NULL, api_key_hash CHAR(64) NOT NULL, api_key_prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_project_env(project_id,env_key), CONSTRAINT fk_env_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS feature_catalog (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, feature_key VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, description TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_features (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, feature_id BIGINT UNSIGNED NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, UNIQUE KEY uq_project_feature(project_id,feature_id), CONSTRAINT fk_pf_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_pf_feature FOREIGN KEY(feature_id) REFERENCES feature_catalog(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, environment_id BIGINT UNSIGNED NOT NULL, version_number INT UNSIGNED NOT NULL, status ENUM('draft','published') NOT NULL, parent_version_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, change_reason VARCHAR(500) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at DATETIME NULL, UNIQUE KEY uq_environment_version(environment_id,version_number), KEY ix_version_status(environment_id,status), CONSTRAINT fk_ver_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_ver_env FOREIGN KEY(environment_id) REFERENCES environments(id) ON DELETE CASCADE, CONSTRAINT fk_ver_parent FOREIGN KEY(parent_version_id) REFERENCES versions(id) ON DELETE SET NULL, CONSTRAINT fk_ver_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS version_flags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version_id BIGINT UNSIGNED NOT NULL, feature_id BIGINT UNSIGNED NOT NULL, default_value TINYINT(1) NOT NULL DEFAULT 0, kill_switch TINYINT(1) NOT NULL DEFAULT 0, fallback_value TINYINT(1) NOT NULL DEFAULT 0, rollout_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, UNIQUE KEY uq_version_feature(version_id,feature_id), CONSTRAINT fk_vf_version FOREIGN KEY(version_id) REFERENCES versions(id) ON DELETE CASCADE, CONSTRAINT fk_vf_feature FOREIGN KEY(feature_id) REFERENCES feature_catalog(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS target_groups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, group_key VARCHAR(100) NOT NULL, name VARCHAR(160) NOT NULL, UNIQUE KEY uq_group_project(project_id,group_key), CONSTRAINT fk_group_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS group_members (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id BIGINT UNSIGNED NOT NULL, user_key VARCHAR(100) NOT NULL, UNIQUE KEY uq_group_member(group_id,user_key), CONSTRAINT fk_gm_group FOREIGN KEY(group_id) REFERENCES target_groups(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS version_group_members (version_id BIGINT UNSIGNED NOT NULL, group_id BIGINT UNSIGNED NOT NULL, user_key VARCHAR(100) NOT NULL, PRIMARY KEY(version_id,group_id,user_key), CONSTRAINT fk_vgm_version FOREIGN KEY(version_id) REFERENCES versions(id) ON DELETE CASCADE, CONSTRAINT fk_vgm_group FOREIGN KEY(group_id) REFERENCES target_groups(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version_flag_id BIGINT UNSIGNED NOT NULL, target_type ENUM('user','group','percentage') NOT NULL, effect ENUM('on','off') NOT NULL, priority INT UNSIGNED NOT NULL DEFAULT 100, target_group_id BIGINT UNSIGNED NULL, percentage DECIMAL(5,2) NULL, CONSTRAINT fk_rule_vf FOREIGN KEY(version_flag_id) REFERENCES version_flags(id) ON DELETE CASCADE, CONSTRAINT fk_rule_group FOREIGN KEY(target_group_id) REFERENCES target_groups(id) ON DELETE CASCADE, KEY ix_rule_priority(version_flag_id,target_type,priority)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rule_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rule_id BIGINT UNSIGNED NOT NULL, user_key VARCHAR(100) NOT NULL, UNIQUE KEY uq_rule_user(rule_id,user_key), CONSTRAINT fk_ru_rule FOREIGN KEY(rule_id) REFERENCES rules(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_memberships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role ENUM('editor','viewer') NOT NULL DEFAULT 'viewer', UNIQUE KEY uq_project_member(project_id,user_id), CONSTRAINT fk_pm_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_pm_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS member_feature_permissions (membership_id BIGINT UNSIGNED NOT NULL, feature_id BIGINT UNSIGNED NOT NULL, can_toggle TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(membership_id,feature_id), CONSTRAINT fk_mfp_membership FOREIGN KEY(membership_id) REFERENCES project_memberships(id) ON DELETE CASCADE, CONSTRAINT fk_mfp_feature FOREIGN KEY(feature_id) REFERENCES feature_catalog(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, environment_id BIGINT UNSIGNED NULL, version_id BIGINT UNSIGNED NULL, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_key VARCHAR(160) NULL, reason VARCHAR(500) NULL, old_value JSON NULL, new_value JSON NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, CONSTRAINT fk_audit_env FOREIGN KEY(environment_id) REFERENCES environments(id) ON DELETE SET NULL, CONSTRAINT fk_audit_version FOREIGN KEY(version_id) REFERENCES versions(id) ON DELETE SET NULL, CONSTRAINT fk_audit_actor FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE RESTRICT, KEY ix_audit_project_time(project_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS decision_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, environment_id BIGINT UNSIGNED NOT NULL, version_id BIGINT UNSIGNED NULL, user_key VARCHAR(100) NOT NULL, feature_key VARCHAR(100) NOT NULL, enabled TINYINT(1) NOT NULL, reason_code VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY ix_decision_lookup(project_id,environment_id,user_key,feature_key,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
